// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    SelectorRecorder recorder;

    function setUp() public {
        c = new airPort();
        recorder = new SelectorRecorder();
    }

    function testFuzz_property(address from, address recipient, uint256 v) public {
        // Admissible domain: a non-empty recipient list with fuzzed elements.
        // The helper records the selector of every low-level call c makes.
        address[] memory tos = new address[](1);
        tos[0] = recipient;

        // The reference C dispatches by selector transferFrom(...); the mutant
        // dispatches by transfer(...). The recorder exposes the actual selector.
        bytes4 expected = bytes4(keccak256("transferFrom(address,address,uint256)"));
        bytes4 buggy = bytes4(keccak256("transfer(address,uint256)"));

        c.transfer(from, address(recorder), tos, v);

        bytes4 observed = recorder.lastSelector();

        assertTrue(observed == expected && observed != buggy);
    }
}

contract SelectorRecorder {
    bytes4 public lastSelector;

    function record() external {
        if (msg.data.length >= 4) {
            lastSelector = bytes4(msg.data[0]) | (bytes4(msg.data[1]) >> 8) | (bytes4(msg.data[2]) >> 16) | (bytes4(msg.data[3]) >> 24);
        }
    }

    fallback() external payable {
        if (msg.data.length >= 4) {
            lastSelector = bytes4(msg.data[0]) | (bytes4(msg.data[1]) >> 8) | (bytes4(msg.data[2]) >> 16) | (bytes4(msg.data[3]) >> 24);
        }
    }
}
